export function translateEuWaveBackendPhrase(source: string, locale: BackendValueEuLocale): string {
  const index = BACKEND_VALUE_EU_LOCALES.indexOf(locale);
  return BACKEND_VALUE_ROWS[source]?.[index] || source;
}
